import{_ as o,o as n,c as a,ak as t}from"./chunks/framework.BNVJvTzl.js";const m=JSON.parse('{"title":"Your daily view","description":"What VERA sends you each morning and evening, and what the console shows you when you open it each day, by role.","frontmatter":{"description":"What VERA sends you each morning and evening, and what the console shows you when you open it each day, by role."},"headers":[],"relativePath":"guide/morning-briefing.md","filePath":"guide/morning-briefing.md"}'),r={name:"guide/morning-briefing.md"};function s(i,e,h,d,l,g){return n(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="your-daily-view" tabindex="-1">Your daily view <a class="header-anchor" href="#your-daily-view" aria-label="Permalink to &quot;Your daily view&quot;">​</a></h1><p>VERA is built around timeliness: seeing where things stand <em>now</em>, not at the end of the month. Two things carry that, a short email each working morning and the console whenever you open it. What you see depends on your role.</p><hr><h2 id="the-morning-email" tabindex="-1">The morning email <a class="header-anchor" href="#the-morning-email" aria-label="Permalink to &quot;The morning email&quot;">​</a></h2><p>Everyone gets one each working morning. It tells you:</p><ul><li><strong>What you recorded on your last working day</strong>, or a plain note that nothing was recorded, with a link to <strong>My time</strong>.</li><li><strong>This week&#39;s planned hours on each of your allocations</strong>, and whether you&#39;re ahead, on track or behind. It&#39;s judged on the days before today, since nobody has recorded today yet at 9am.</li></ul><p>Managers, owners and admins also get an <strong>At a glance</strong> section, the same summary as the console home page: projects needing setup or off course, who&#39;s over capacity this week, and, for owners, admins and Manager Plus, last month&#39;s money.</p><p>Email comes first. People who still use Slack may get the message there instead.</p><hr><h2 id="the-evening-nudge" tabindex="-1">The evening nudge <a class="header-anchor" href="#the-evening-nudge" aria-label="Permalink to &quot;The evening nudge&quot;">​</a></h2><p>A reminder goes out in the late afternoon only when you&#39;ve recorded less than your normal day. Part-time schedules get their own target, so nobody is nagged after finishing a shorter day. Admins and vendors don&#39;t get it.</p><hr><h2 id="for-team-members-in-the-console" tabindex="-1">For team members in the console <a class="header-anchor" href="#for-team-members-in-the-console" aria-label="Permalink to &quot;For team members in the console&quot;">​</a></h2><p>Open <strong>Time</strong>, then <strong>My time</strong>. You&#39;ll see your week, your allocations with their task links, and <strong>Quick log</strong> for adding the day&#39;s work in a few seconds. Log as you go and your record stays current.</p><p>The <strong>Time off</strong> tab shows the status of any holiday or leave you&#39;ve requested, and the <strong>Calendar</strong> tab shows upcoming company holidays that affect your week.</p><hr><h2 id="for-managers-and-owners-in-the-console" tabindex="-1">For managers and owners in the console <a class="header-anchor" href="#for-managers-and-owners-in-the-console" aria-label="Permalink to &quot;For managers and owners in the console&quot;">​</a></h2><p>The <a href="https://app.getvera.site/console" target="_blank" rel="noreferrer">console</a> opens on a one-screen brief: <strong>Money</strong> (owners, admins and Manager Plus), <strong>Projects</strong>, and <strong>People this week</strong>, each linking to the page behind it, above your list of projects.</p><p><strong>Needs you</strong> collects everything waiting on you in one place: time-off requests, time approvals, unresolved items, and projects that still need setup.</p><p><strong>Staffing</strong> covers allocations, liabilities, vendors, capacity across the coming weeks, and each month&#39;s recorded hours.</p><p><strong>Money</strong> (owners, admins and Manager Plus) holds the financial views: profit and loss, estimates against actuals, segmentation, forecast, billing and LER.</p><p><strong>Performance</strong> (owners, admins and Manager Plus) holds the team views: contributions, project managers, the portfolio, and recorded hours.</p><p>Projects that are off the plan line, over or under by a meaningful margin, surface with clear status flags, so the things most worth your attention find you rather than the other way round.</p>',23)])])}const u=o(r,[["render",s]]);export{m as __pageData,u as default};
